/**
 * ternary.h — Definiciones core del kernel ternario ancestral
 * 
 * Conceptos:
 * - Ternary: {-1, 0, +1} como unidad básica
 * - Base 60 (Babilónico): direcciones de memoria
 * - Ciclos Mayas: planificación de procesos
 * - Quipu: sistema de archivos
 */

#ifndef TERNARY_H
#define TERNARY_H

// =============================================================================
// TIPOS TERNARIOS
// =============================================================================

// Trit balanceado: -1, 0, +1
typedef int8_t trit_t;

// Valor ternario empaquetado (3 trits en 5 bits)
typedef uint8_t trit_packed_t;

// Dirección babilónica (base 60)
typedef struct {
    uint8_t high;   // dígito alto (0-59)
    uint8_t low;    // dígito bajo (0-59)
} __attribute__((packed)) babilonian_addr_t;

// ID de proceso maya
typedef struct {
    uint16_t tzolkin;   // 1-260 (ciclo sagrado)
    uint8_t haab;       // 1-365 (año solar)
} __attribute__((packed)) maya_pid_t;

// =============================================================================
// CONSTANTES
// =============================================================================

#define TRIT_NEG    (-1)
#define TRIT_ZERO   (0)
#define TRIT_POS    (1)

#define BASE_60     60
#define TZOLKIN     260     // Días en ciclo sagrado Maya
#define HAAB        365     // Días en año Maya
#define MAX_PROCS   33      // Máximo procesos (mod-33)
#define MEM_BLOCKS  60      // Bloques de memoria (base 60)
#define BLOCK_SIZE  60      // Bytes por bloque

// =============================================================================
// OPERACIONES TERNARIAS BÁSICAS
// =============================================================================

// Suma ternaria: {-1,0,+1} + {-1,0,+1} → {-2,-1,0,+1,+2}
static inline trit_t trit_add(trit_t a, trit_t b) {
    trit_t sum = a + b;
    if (sum > 1) return 1;
    if (sum < -1) return -1;
    return sum;
}

// Multiplicación ternaria
static inline trit_t trit_mul(trit_t a, trit_t b) {
    if (a == 0 || b == 0) return 0;
    return (a == b) ? 1 : -1;
}

// Negación ternaria
static inline trit_t trit_neg(trit_t a) {
    return -a;
}

// Comparación ternaria
static inline trit_t trit_cmp(trit_t a, trit_t b) {
    if (a > b) return 1;
    if (a < b) return -1;
    return 0;
}

// =============================================================================
// EMPAQUETADO DE TRITS (3 trits → 5 bits)
// =============================================================================

static inline trit_packed_t pack_trits(trit_t t1, trit_t t2, trit_t t3) {
    uint8_t v1 = (uint8_t)(t1 + 1);  // 0, 1, 2
    uint8_t v2 = (uint8_t)(t2 + 1);
    uint8_t v3 = (uint8_t)(t3 + 1);
    return v1 * 9 + v2 * 3 + v3;     // 0-24
}

static inline void unpack_trits(trit_packed_t packed, trit_t* t1, trit_t* t2, trit_t* t3) {
    *t1 = (trit_t)((packed / 9) % 3) - 1;
    *t2 = (trit_t)((packed / 3) % 3) - 1;
    *t3 = (trit_t)(packed % 3) - 1;
}

// =============================================================================
// DIRECCIONES BABILÓNICAS (Base 60)
// =============================================================================

// Convertir dirección lineal a babilónica
static inline babilonian_addr_t linear_to_babilonian(uint16_t addr) {
    babilonian_addr_t result;
    result.high = addr / BASE_60;
    result.low = addr % BASE_60;
    return result;
}

// Convertir dirección babilónica a lineal
static inline uint16_t babilonian_to_linear(babilonian_addr_t addr) {
    return addr.high * BASE_60 + addr.low;
}

// =============================================================================
// IDs MAYAS
// =============================================================================

// Crear ID maya desde contador
static inline maya_pid_t make_maya_pid(uint32_t counter) {
    maya_pid_t pid;
    pid.tzolkin = (counter % TZOLKIN) + 1;
    pid.haab = (counter % HAAB) + 1;
    return pid;
}

// Comparar IDs mayas
static inline trit_t compare_maya_pid(maya_pid_t a, maya_pid_t b) {
    if (a.tzolkin != b.tzolkin) {
        return (a.tzolkin > b.tzolkin) ? 1 : -1;
    }
    if (a.haab != b.haab) {
        return (a.haab > b.haab) ? 1 : -1;
    }
    return 0;
}

#endif // TERNARY_H

/**
 * memory.c — Gestor de memoria en Base 60 (Babilónico)
 * 
 * Memoria organizada en 60 bloques de 60 bytes cada uno
 * Total: 3,600 bytes (3.5KB)
 * 
 * Cada bloque tiene un "color" (tipo) como los quipus:
 * - 0: libre
 * - 1: kernel
 * - 2: datos de proceso
 * - 3: stack
 * - 4: código
 */

#include "../include/ternary.h"

// =============================================================================
// ESTRUCTURAS
// =============================================================================

// Bloque de memoria
typedef struct {
    uint8_t data[BLOCK_SIZE];    // Datos del bloque
    uint8_t color;               // Tipo de bloque (0-7)
    uint8_t owner;               // ID del proceso dueño
    uint8_t flags;               // Bits: [used][dirty][locked][...]
} __attribute__((packed)) mem_block_t;

// Mapa de memoria (quipu simplificado)
typedef struct {
    uint8_t knot_positions[MEM_BLOCKS];  // Posición de cada "nudo"
    uint8_t knot_colors[MEM_BLOCKS];     // Color de cada "nudo"
    uint8_t total_used;                  // Bloques en uso
    uint8_t total_free;                  // Bloques libres
} __attribute__((packed)) memory_map_t;

// =============================================================================
// VARIABLES GLOBALES
// =============================================================================

static mem_block_t memory[MEM_BLOCKS];
static memory_map_t map;

// =============================================================================
// FUNCIONES
// =============================================================================

// Inicializar memoria
void mem_init() {
    // Limpiar todos los bloques
    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        for (uint8_t j = 0; j < BLOCK_SIZE; j++) {
            memory[i].data[j] = 0;
        }
        memory[i].color = 0;   // libre
        memory[i].owner = 0;   // sin dueño
        memory[i].flags = 0;

        // Inicializar mapa quipu
        map.knot_positions[i] = i;
        map.knot_colors[i] = 0;
    }

    // Marcar bloques del kernel
    for (uint8_t i = 0; i < 5; i++) {
        memory[i].color = 1;    // kernel
        memory[i].owner = 0;    // kernel = PID 0
        memory[i].flags = 0x08; // locked
        map.knot_colors[i] = 1;
    }

    map.total_used = 5;
    map.total_free = MEM_BLOCKS - 5;
}

// Asignar bloque (con color)
int8_t mem_alloc(uint8_t owner, uint8_t color) {
    // Buscar primer bloque libre (residuo mod-33 para balance)
    uint8_t start = (map.total_used * 7) % MEM_BLOCKS;  // Hash simple

    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        uint8_t idx = (start + i) % MEM_BLOCKS;

        if (memory[idx].color == 0) {  // libre
            memory[idx].color = color;
            memory[idx].owner = owner;
            memory[idx].flags = 0x01;  // used

            map.knot_colors[idx] = color;
            map.total_used++;
            map.total_free--;

            return idx;  // Retorna índice del bloque
        }
    }

    return -1;  // Sin memoria
}

// Liberar bloque
int8_t mem_free(uint8_t block_idx) {
    if (block_idx >= MEM_BLOCKS) return -1;
    if (memory[block_idx].flags & 0x08) return -1;  // locked

    // Limpiar bloque
    for (uint8_t j = 0; j < BLOCK_SIZE; j++) {
        memory[block_idx].data[j] = 0;
    }

    memory[block_idx].color = 0;
    memory[block_idx].owner = 0;
    memory[block_idx].flags = 0;

    map.knot_colors[block_idx] = 0;
    map.total_used--;
    map.total_free++;

    return 0;
}

// Liberar todos los bloques de un proceso
void mem_free_all(uint8_t owner) {
    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        if (memory[i].owner == owner && !(memory[i].flags & 0x08)) {
            mem_free(i);
        }
    }
}

// Leer byte de memoria (dirección babilónica)
int8_t mem_read(babilonian_addr_t addr, uint8_t* value) {
    uint16_t linear = babilonian_to_linear(addr);
    uint8_t block = linear / BLOCK_SIZE;
    uint8_t offset = linear % BLOCK_SIZE;

    if (block >= MEM_BLOCKS) return -1;
    if (memory[block].color == 0) return -1;  // libre

    *value = memory[block].data[offset];
    return 0;
}

// Escribir byte en memoria (dirección babilónica)
int8_t mem_write(babilonian_addr_t addr, uint8_t value) {
    uint16_t linear = babilonian_to_linear(addr);
    uint8_t block = linear / BLOCK_SIZE;
    uint8_t offset = linear % BLOCK_SIZE;

    if (block >= MEM_BLOCKS) return -1;
    if (memory[block].flags & 0x08) return -1;  // locked

    memory[block].data[offset] = value;
    memory[block].flags |= 0x02;  // dirty
    return 0;
}

// Obtener dirección base de un bloque
babilonian_addr_t mem_get_base(uint8_t block_idx) {
    uint16_t linear = block_idx * BLOCK_SIZE;
    return linear_to_babilonian(linear);
}

// Obtener estado de la memoria (para debug)
void mem_get_status(uint8_t* used, uint8_t* free, uint8_t* locked) {
    *used = map.total_used;
    *free = map.total_free;

    uint8_t lock_count = 0;
    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        if (memory[i].flags & 0x08) lock_count++;
    }
    *locked = lock_count;
}

// Imprimir mapa de memoria (debug)
void mem_print_map() {
    // Esta función sería implementada con I/O de video
    // Por ahora, solo retorna información
    uint8_t used, free, locked;
    mem_get_status(&used, &free, &locked);

    // En un sistema real, imprimiría:
    // "Memory: X used, Y free, Z locked"
    // Con colores显示 los bloques usados
}

/**
 * scheduler.c — Planificador basado en Ciclos Mayas
 * 
 * Procesos planificados en ciclos de:
 * - Tzolkin: 260 días (ciclo sagrado)
 * - Haab: 365 días (año solar)
 * 
 * Cada "día" = quantum de CPU
 * Los procesos se planifican según su "fecha" en el calendario Maya
 */

#include "../include/ternary.h"

// =============================================================================
// ESTRUCTURAS
// =============================================================================

// Estados del proceso (ternario)
typedef enum {
    PROC_DEAD = -1,     // Muerto
    PROC_SLEEPING = 0,  // Dormido
    PROC_ACTIVE = 1     // Activo
} proc_state_t;

// Proceso
typedef struct {
    maya_pid_t pid;         // ID maya
    proc_state_t state;     // Estado ternario
    trit_t priority;        // Prioridad: -1=baja, 0=media, +1=alta
    uint8_t memory_block;   // Bloque de memoria asignado
    uint16_t cpu_cycles;    // Ciclos de CPU consumidos
    uint8_t quantum;        // Quantum actual (0-2)
    uint8_t parent;         // PID del padre
    uint8_t children[4];    // PIDs de hijos (máximo 4)
    uint8_t n_children;     // Número de hijos
} __attribute__((packed)) process_t;

// Estado del scheduler
typedef struct {
    uint32_t global_tick;           // Tick global del sistema
    uint8_t current_pid;            // Índice del proceso actual
    uint8_t tzolkin_day;            // Día actual en Tzolkin (1-260)
    uint8_t haab_day;               // Día actual en Haab (1-365)
    uint8_t active_count;           // Procesos activos
    trit_t system_load;             // Carga del sistema: -1=baja, 0=media, +1=alta
} __attribute__((packed)) scheduler_state_t;

// =============================================================================
// VARIABLES GLOBALES
// =============================================================================

static process_t processes[MAX_PROCS];
static scheduler_state_t scheduler;

// =============================================================================
// FUNCIONES
// =============================================================================

// Inicializar scheduler
void sched_init() {
    // Limpiar procesos
    for (uint8_t i = 0; i < MAX_PROCS; i++) {
        processes[i].pid = make_maya_pid(0);
        processes[i].state = PROC_DEAD;
        processes[i].priority = 0;
        processes[i].memory_block = 0;
        processes[i].cpu_cycles = 0;
        processes[i].quantum = 0;
        processes[i].parent = 0;
        processes[i].n_children = 0;

        for (uint8_t j = 0; j < 4; j++) {
            processes[i].children[j] = 0;
        }
    }

    // Inicializar scheduler
    scheduler.global_tick = 0;
    scheduler.current_pid = 0;
    scheduler.tzolkin_day = 1;
    scheduler.haab_day = 1;
    scheduler.active_count = 0;
    scheduler.system_load = 0;

    // Crear proceso init (PID 0)
    processes[0].pid = make_maya_pid(0);
    processes[0].state = PROC_ACTIVE;
    processes[0].priority = 0;  // prioridad media
    processes[0].memory_block = 0;
    scheduler.active_count = 1;
}

// Crear proceso
int8_t sched_create(uint8_t parent, trit_t priority) {
    // Buscar slot libre
    for (uint8_t i = 1; i < MAX_PROCS; i++) {
        if (processes[i].state == PROC_DEAD) {
            // Crear nuevo proceso con ID maya
            processes[i].pid = make_maya_pid(scheduler.global_tick + i);
            processes[i].state = PROC_SLEEPING;
            processes[i].priority = priority;
            processes[i].memory_block = 0;  // Se asignará después
            processes[i].cpu_cycles = 0;
            processes[i].quantum = 0;
            processes[i].parent = parent;
            processes[i].n_children = 0;

            // Agregar a hijos del padre
            if (parent < MAX_PROCS && processes[parent].n_children < 4) {
                processes[parent].children[processes[parent].n_children] = i;
                processes[parent].n_children++;
            }

            scheduler.active_count++;
            return i;
        }
    }

    return -1;  // Sin espacio
}

// Matar proceso
int8_t sched_kill(uint8_t pid) {
    if (pid >= MAX_PROCS) return -1;
    if (processes[pid].state == PROC_DEAD) return -1;
    if (pid == 0) return -1;  // No se puede matar init

    // Liberar hijos recursivamente
    for (uint8_t i = 0; i < processes[pid].n_children; i++) {
        sched_kill(processes[pid].children[i]);
    }

    // Marcar como muerto
    processes[pid].state = PROC_DEAD;
    processes[pid].memory_block = 0;
    scheduler.active_count--;

    return 0;
}

// Dormir proceso
int8_t sched_sleep(uint8_t pid) {
    if (pid >= MAX_PROCS) return -1;
    if (processes[pid].state == PROC_DEAD) return -1;

    processes[pid].state = PROC_SLEEPING;
    return 0;
}

// Despertar proceso
int8_t sched_wake(uint8_t pid) {
    if (pid >= MAX_PROCS) return -1;
    if (processes[pid].state == PROC_DEAD) return -1;

    processes[pid].state = PROC_ACTIVE;
    return 0;
}

// Actualizar calendario Maya
static void update_maya_calendar() {
    scheduler.global_tick++;

    // Avanzar Tzolkin (1-260)
    scheduler.tzolkin_day++;
    if (scheduler.tzolkin_day > TZOLKIN) {
        scheduler.tzolkin_day = 1;
    }

    // Avanzar Haab (1-365)
    scheduler.haab_day++;
    if (scheduler.haab_day > HAAB) {
        scheduler.haab_day = 1;
    }
}

// Seleccionar siguiente proceso (round-robin ternario)
static uint8_t select_next() {
    uint8_t start = scheduler.current_pid;
    trit_t best_priority = -2;  // Menor que cualquier prioridad válida
    uint8_t best_pid = 0;

    // Buscar proceso con mayor prioridad
    for (uint8_t i = 0; i < MAX_PROCS; i++) {
        uint8_t idx = (start + i + 1) % MAX_PROCS;

        if (processes[idx].state == PROC_ACTIVE) {
            // Comparar prioridad (ternario)
            trit_t cmp = trit_cmp(processes[idx].priority, best_priority);

            if (cmp == 1 || (cmp == 0 && processes[idx].quantum < 3)) {
                best_priority = processes[idx].priority;
                best_pid = idx;
            }
        }
    }

    return best_pid;
}

// Actualizar carga del sistema
static void update_system_load() {
    uint8_t active = scheduler.active_count;

    if (active <= 3) {
        scheduler.system_load = -1;  // baja
    } else if (active <= 10) {
        scheduler.system_load = 0;   // media
    } else {
        scheduler.system_load = 1;   // alta
    }
}

// Tick del scheduler
uint8_t sched_tick() {
    // Actualizar calendario
    update_maya_calendar();

    // Seleccionar siguiente proceso
    uint8_t next = select_next();

    if (next != scheduler.current_pid) {
        // Cambio de contexto
        processes[scheduler.current_pid].quantum = 0;
        scheduler.current_pid = next;
    }

    // Ejecutar quantum actual
    processes[scheduler.current_pid].quantum++;
    processes[scheduler.current_pid].cpu_cycles++;

    // Si quantum completado (3 ciclos), cambiar proceso
    if (processes[scheduler.current_pid].quantum >= 3) {
        processes[scheduler.current_pid].quantum = 0;
        return 1;  // Context switch
    }

    return 0;  // Misma tarea
}

// Obtener proceso actual
uint8_t sched_get_current() {
    return scheduler.current_pid;
}

// Obtener estado del scheduler
void sched_get_state(uint32_t* tick, uint8_t* tzolkin, uint8_t* haab, trit_t* load) {
    *tick = scheduler.global_tick;
    *tzolkin = scheduler.tzolkin_day;
    *haab = scheduler.haab_day;
    *load = scheduler.system_load;
}

// Obtener info de un proceso
int8_t sched_get_info(uint8_t pid, process_t* info) {
    if (pid >= MAX_PROCS) return -1;

    *info = processes[pid];
    return 0;
}

// Syscall: fork
int8_t sys_fork() {
    return sched_create(scheduler.current_pid, 
                       processes[scheduler.current_pid].priority);
}

// Syscall: exit
int8_t sys_exit() {
    return sched_kill(scheduler.current_pid);
}

// Syscall: sleep
int8_t sys_sleep() {
    return sched_sleep(scheduler.current_pid);
}

// Syscall: wake
int8_t sys_wake(uint8_t pid) {
    return sched_wake(pid);
}

/**
 * kernel.c — Kernel Ternario Ancestral
 * 
 * Sistema operativo ultra-liviano basado en:
 * - Lógica ternaria {-1, 0, +1}
 * - Memoria en Base 60 (Babilónico)
 * - Planificación por ciclos Mayas
 * - Sistema de archivos Quipu
 * 
 * Tamaño total: ~4KB de código
