// =============================================================================
// I/O — Puerto serial (0x3F8)
// =============================================================================

#define SERIAL_PORT 0x3F8

void serial_init() {
    // Configurar puerto serial a 9600 baud
    outb(SERIAL_PORT + 1, 0x00);    // Disable interrupts
    outb(SERIAL_PORT + 3, 0x80);    // Enable DLAB
    outb(SERIAL_PORT + 0, 0x0C);    // Set divisor lo byte (12 -> 9600 baud)
    outb(SERIAL_PORT + 1, 0x00);    // Set divisor hi byte
    outb(SERIAL_PORT + 3, 0x03);    // 8 bits, no parity, one stop bit
    outb(SERIAL_PORT + 2, 0xC7);    // Enable FIFO
    outb(SERIAL_PORT + 4, 0x0B);    // IRQs enabled, RTS/DSR set
}

void serial_putc(char c) {
    while (!(inb(SERIAL_PORT + 5) & 0x20));
    outb(SERIAL_PORT, c);
}

void serial_puts(const char* str) {
    while (*str) {
        serial_putc(*str++);
    }
}

void serial_print_trit(trit_t t) {
    if (t == -1) serial_putc('-');
    else if (t == 0) serial_putc('0');
    else serial_putc('+');
}

void serial_print_num(int16_t num) {
    char buf[8];
    int i = 0;

    if (num < 0) {
        serial_putc('-');
        num = -num;
    }

    if (num == 0) {
        serial_putc('0');
        return;
    }

    while (num > 0) {
        buf[i++] = '0' + (num % 10);
        num /= 10;
    }

    while (i > 0) {
        serial_putc(buf[--i]);
    }
}

// =============================================================================
// VGA — Pantalla de texto (0xB8000)
// =============================================================================

#define VGA_ADDR 0xB8000
#define VGA_WIDTH 80
#define VGA_HEIGHT 25

static uint16_t* vga_buffer = (uint16_t*)VGA_ADDR;
static uint8_t vga_x = 0;
static uint8_t vga_y = 0;
static uint8_t vga_color = 0x07;  // Blanco sobre negro

void vga_init() {
    // Limpiar pantalla
    for (int i = 0; i < VGA_WIDTH * VGA_HEIGHT; i++) {
        vga_buffer[i] = 0x0720;  // Espacio en blanco
    }
    vga_x = 0;
    vga_y = 0;
}

void vga_putc(char c) {
    if (c == '\n') {
        vga_x = 0;
        vga_y++;
        if (vga_y >= VGA_HEIGHT) vga_y = 0;
        return;
    }

    uint16_t entry = (vga_color << 8) | c;
    vga_buffer[vga_y * VGA_WIDTH + vga_x] = entry;

    vga_x++;
    if (vga_x >= VGA_WIDTH) {
        vga_x = 0;
        vga_y++;
        if (vga_y >= VGA_HEIGHT) vga_y = 0;
    }
}

void vga_puts(const char* str) {
    while (*str) {
        vga_putc(*str++);
    }
}

void vga_print_trit(trit_t t) {
    if (t == -1) {
        vga_color = 0x04;  // Rojo
        vga_putc('-');
    } else if (t == 0) {
        vga_color = 0x07;  // Blanco
        vga_putc('0');
    } else {
        vga_color = 0x02;  // Verde
        vga_putc('+');
    }
    vga_color = 0x07;  // Restaurar
}

// =============================================================================
// SISTEMA DE ARCHIVOS QUIPU
// =============================================================================

#define MAX_FILES 33  // mod-33

typedef struct {
    char name[8];       // Nombre (8 chars)
    uint8_t size;       // Tamaño en bloques
    uint8_t block;      // Bloque inicial
    uint8_t type;       // Tipo (0=archivo, 1=directorio, 2=ejecutable)
    uint8_t permissions; // Permisos (bits)
} __attribute__((packed)) quipu_file_t;

static quipu_file_t files[MAX_FILES];
static uint8_t n_files = 0;

void fs_init() {
    for (uint8_t i = 0; i < MAX_FILES; i++) {
        for (uint8_t j = 0; j < 8; j++) {
            files[i].name[j] = 0;
        }
        files[i].size = 0;
        files[i].block = 0;
        files[i].type = 0;
        files[i].permissions = 0;
    }

    // Crear directorio raíz
    for (uint8_t j = 0; j < 8; j++) {
        files[0].name[j] = "/";
    }
    files[0].type = 1;  // directorio
    files[0].block = 0;
    n_files = 1;
}

int8_t fs_create(const char* name, uint8_t type) {
    if (n_files >= MAX_FILES) return -1;

    // Copiar nombre
    uint8_t i;
    for (i = 0; i < 8 && name[i]; i++) {
        files[n_files].name[i] = name[i];
    }
    for (; i < 8; i++) {
        files[n_files].name[i] = 0;
    }

    files[n_files].type = type;
    files[n_files].size = 0;
    files[n_files].block = 0;
    files[n_files].permissions = 0x07;  // rw-

    n_files++;
    return n_files - 1;
}

int8_t fs_find(const char* name) {
    for (uint8_t i = 0; i < n_files; i++) {
        uint8_t match = 1;
        for (uint8_t j = 0; j < 8; j++) {
            if (files[i].name[j] != name[j]) {
                match = 0;
                break;
            }
        }
        if (match) return i;
    }
    return -1;
}

int8_t fs_delete(uint8_t file_id) {
    if (file_id >= n_files) return -1;
    if (file_id == 0) return -1;  // No borrar raíz

    // Mover archivos hacia atrás
    for (uint8_t i = file_id; i < n_files - 1; i++) {
        files[i] = files[i + 1];
    }

    n_files--;
    return 0;
}

// =============================================================================
// INTERRUPCiones — IDT básica
// =============================================================================

typedef struct {
    uint16_t base_lo;
    uint16_t sel;
    uint8_t always0;
    uint8_t flags;
    uint16_t base_hi;
} __attribute__((packed)) idt_entry_t;

typedef struct {
    uint16_t limit;
    uint32_t base;
} __attribute__((packed)) idt_ptr_t;

static idt_entry_t idt[256];
static idt_ptr_t idtp;

void idt_set_gate(uint8_t num, uint32_t base, uint16_t sel, uint8_t flags) {
    idt[num].base_lo = base & 0xFFFF;
    idt[num].base_hi = (base >> 16) & 0xFFFF;
    idt[num].sel = sel;
    idt[num].always0 = 0;
    idt[num].flags = flags;
}

void idt_install() {
    idtp.limit = sizeof(idt_entry_t) * 256 - 1;
    idtp.base = (uint32_t)&idt;

    for (uint8_t i = 0; i < 256; i++) {
        idt_set_gate(i, 0, 0, 0);
    }

    // Cargar IDT
    asm volatile("lidt %0" : : "m"(idtp));
}

// =============================================================================
// HANDLERS DE INTERRUPCIONES
// =============================================================================

void isr_handler(uint32_t interrupt) {
    if (interrupt == 32) {
        // Timer tick — scheduler
        uint8_t switch_task = sched_tick();

        if (switch_task) {
            // Aquí iría el cambio de contexto real
            // Por ahora, solo imprimimos
            serial_puts("[TICK] Context switch\n");
        }
    } else if (interrupt == 33) {
        // Teclado
        uint8_t scancode = inb(0x60);
        // Manejar tecla...
    }
}

// =============================================================================
// KERNEL MAIN
// =============================================================================

void kernel_main() {
    // Inicializar subsistemas
    serial_init();
    vga_init();

    // Mostrar banner
    vga_puts("========================================\n");
    vga_puts("   TERNARY ANCESTRAL KERNEL v0.1\n");
    vga_puts("========================================\n\n");

    vga_puts("Initializing memory (Base 60)...\n");
    mem_init();

    vga_puts("Initializing scheduler (Maya cycles)...\n");
    sched_init();

    vga_puts("Initializing filesystem (Quipu)...\n");
    fs_init();

    vga_puts("Installing IDT...\n");
    idt_install();

    vga_puts("\n");
    vga_puts("System ready.\n");
    vga_puts("\n");

    // Demo: crear procesos
    vga_puts("Creating processes...\n");

    int8_t proc1 = sched_create(0, 1);   // Alta prioridad
    int8_t proc2 = sched_create(0, 0);   // Media prioridad
    int8_t proc3 = sched_create(0, -1);  // Baja prioridad

    vga_puts("  PID 1 (high):   ");
    vga_print_trit(1);
    vga_puts("\n");

    vga_puts("  PID 2 (medium): ");
    vga_print_trit(0);
    vga_puts("\n");

    vga_puts("  PID 3 (low):    ");
    vga_print_trit(-1);
    vga_puts("\n");

    // Demo: memoria
    vga_puts("\nMemory blocks (Babylonian):\n");
    uint8_t mem_used, mem_free, mem_locked;
    mem_get_status(&mem_used, &mem_free, &mem_locked);

    vga_puts("  Used:  ");
    serial_print_num(mem_used);
    vga_puts("\n");

    vga_puts("  Free:  ");
    serial_print_num(mem_free);
    vga_puts("\n");

    vga_puts("  Locked: ");
    serial_print_num(mem_locked);
    vga_puts("\n");

    // Demo: archivos
    vga_puts("\nFiles (Quipu):\n");
    fs_create("test.bin", 2);
    fs_create("data.txt", 0);
    fs_create("config", 1);

    vga_puts("  Created: test.bin\n");
    vga_puts("  Created: data.txt\n");
    vga_puts("  Created: config\n");

    // Demo: calendar Maya
    vga_puts("\nMaya Calendar:\n");
    uint32_t tick;
    uint8_t tzolkin, haab;
    trit_t load;
    sched_get_state(&tick, &tzolkin, &haab, &load);

    vga_puts("  Global tick: ");
    serial_print_num(tick);
    vga_puts("\n");

    vga_puts("  Tzolkin day: ");
    serial_print_num(tzolkin);
    vga_puts("/260\n");

    vga_puts("  Haab day:    ");
    serial_print_num(haab);
    vga_puts("/365\n");

    vga_puts("\n");
    vga_puts("Kernel running. Type commands:\n");
    vga_puts("  ps   - List processes\n");
    vga_puts("  mem  - Memory status\n");
    vga_puts("  fs   - List files\n");
    vga_puts("  cal  - Maya calendar\n");
    vga_puts("  halt - Shutdown\n");
    vga_puts("\n");

    // Loop principal
    char cmd_buf[16];
    uint8_t cmd_idx = 0;

    while (1) {
        // Leer teclado (simplificado)
        if (inb(0x64) & 1) {
            uint8_t scancode = inb(0x60);

            // Convertir scancode a ASCII (simplificado)
            if (scancode < 0x80) {
                char c = 0;
                if (scancode >= 0x02 && scancode <= 0x0B) {
                    c = '0' + (scancode - 0x02);
                } else if (scancode >= 0x1E && scancode <= 0x26) {
                    c = 'a' + (scancode - 0x1E);
                } else if (scancode == 0x1C) {
                    // Enter
                    cmd_buf[cmd_idx] = 0;

                    // Procesar comando
                    if (cmd_buf[0] == 'p' && cmd_buf[1] == 's') {
                        vga_puts("\nProcesses:\n");
                        for (uint8_t i = 0; i < MAX_PROCS; i++) {
                            // Mostrar procesos activos
                        }
                    } else if (cmd_buf[0] == 'm' && cmd_buf[1] == 'e' && cmd_buf[2] == 'm') {
                        vga_puts("\nMemory: ");
                        serial_print_num(mem_used);
                        vga_puts(" used, ");
                        serial_print_num(mem_free);
                        vga_puts(" free\n");
                    } else if (cmd_buf[0] == 'c' && cmd_buf[1] == 'a' && cmd_buf[2] == 'l') {
                        vga_puts("\nMaya Calendar:\n");
                        vga_puts("  Tzolkin: ");
                        serial_print_num(tzolkin);
                        vga_puts("/260\n");
                        vga_puts("  Haab: ");
                        serial_print_num(haab);
                        vga_puts("/365\n");
                    } else if (cmd_buf[0] == 'h' && cmd_buf[1] == 'a' && cmd_buf[2] == 'l' && cmd_buf[3] == 't') {
                        vga_puts("\nShutting down...\n");
                        while (1);
                    }

                    vga_putc('\n');
                    cmd_idx = 0;
                } else if (scancode == 0x0E) {
                    // Backspace
                    if (cmd_idx > 0) {
                        cmd_idx--;
                        vga_putc('\b');
                    }
                } else if (c) {
                    cmd_buf[cmd_idx++] = c;
                    vga_putc(c);
                }
            }
        }

        // Yield CPU
        asm volatile("hlt");
    }
}

/**
 * ternary.h — Definiciones core del kernel ternario ancestral (v2)
 * 
 * Corregido:
 * - Agregados outb/inb como inline assembly
 * - Fix return types para(mem_alloc, mem_get_base)
 * - Agregadas validaciones
 * - Agregadas funciones de libc ternaria
 */

#ifndef TERNARY_H
#define TERNARY_H

#include <stdint.h>

// =============================================================================
// I/O PORTS — Inline assembly para x86
// =============================================================================

static inline void outb(uint16_t port, uint8_t val) {
    asm volatile("outb %0, %1" : : "a"(val), "Nd"(port));
}

static inline uint8_t inb(uint16_t port) {
    uint8_t ret;
    asm volatile("inb %1, %0" : "=a"(ret) : "Nd"(port));
    return ret;
}

static inline void io_wait(void) {
    outb(0x80, 0);
}

// =============================================================================
// TIPOS TERNARIOS
// =============================================================================

typedef int8_t trit_t;
typedef uint8_t trit_packed_t;

typedef struct {
    uint8_t high;
    uint8_t low;
} __attribute__((packed)) babilonian_addr_t;

typedef struct {
    uint16_t tzolkin;
    uint8_t haab;
} __attribute__((packed)) maya_pid_t;

// =============================================================================
// CONSTANTES
// =============================================================================

#define TRIT_NEG    (-1)
#define TRIT_ZERO   (0)
#define TRIT_POS    (1)

#define BASE_60     60
#define TZOLKIN     260
#define HAAB        365
#define MAX_PROCS   33
#define MEM_BLOCKS  60
#define BLOCK_SIZE  60

#define COLOR_FREE      0
#define COLOR_KERNEL    1
#define COLOR_PROCESS   2
#define COLOR_STACK     3
#define COLOR_CODE      4
#define COLOR_DATA      5

// =============================================================================
// OPERACIONES TERNARIAS
// =============================================================================

static inline trit_t trit_add(trit_t a, trit_t b) {
    trit_t sum = a + b;
    if (sum > 1) return 1;
    if (sum < -1) return -1;
    return sum;
}

static inline trit_t trit_mul(trit_t a, trit_t b) {
    if (a == 0 || b == 0) return 0;
    return (a == b) ? 1 : -1;
}

static inline trit_t trit_neg(trit_t a) {
    return -a;
}

static inline trit_t trit_cmp(trit_t a, trit_t b) {
    if (a > b) return 1;
    if (a < b) return -1;
    return 0;
}

// =============================================================================
// EMPAQUETADO DE TRITS
// =============================================================================

static inline trit_packed_t pack_trits(trit_t t1, trit_t t2, trit_t t3) {
    uint8_t v1 = (uint8_t)(t1 + 1);
    uint8_t v2 = (uint8_t)(t2 + 1);
    uint8_t v3 = (uint8_t)(t3 + 1);
    return v1 * 9 + v2 * 3 + v3;
}

static inline void unpack_trits(trit_packed_t packed, trit_t* t1, trit_t* t2, trit_t* t3) {
    *t1 = (trit_t)((packed / 9) % 3) - 1;
    *t2 = (trit_t)((packed / 3) % 3) - 1;
    *t3 = (trit_t)(packed % 3) - 1;
}

// =============================================================================
// DIRECCIONES BABILÓNICAS
// =============================================================================

static inline babilonian_addr_t linear_to_babilonian(uint16_t addr) {
    babilonian_addr_t result;
    result.high = addr / BASE_60;
    result.low = addr % BASE_60;
    return result;
}

static inline uint16_t babilonian_to_linear(babilonian_addr_t addr) {
    return addr.high * BASE_60 + addr.low;
}

// =============================================================================
// IDs MAYAS
// =============================================================================

static inline maya_pid_t make_maya_pid(uint32_t counter) {
    maya_pid_t pid;
    pid.tzolkin = (counter % TZOLKIN) + 1;
    pid.haab = (counter % HAAB) + 1;
    return pid;
}

static inline trit_t compare_maya_pid(maya_pid_t a, maya_pid_t b) {
    if (a.tzolkin != b.tzolkin) {
        return (a.tzolkin > b.tzolkin) ? 1 : -1;
    }
    if (a.haab != b.haab) {
        return (a.haab > b.haab) ? 1 : -1;
    }
    return 0;
}

// =============================================================================
// LIBC TERNARIA MÍNIMA
// =============================================================================

static inline uint16_t strlen_t(const char* str) {
    uint16_t len = 0;
    while (str[len]) len++;
    return len;
}

static inline int8_t strcmp_t(const char* a, const char* b) {
    while (*a && *b) {
        if (*a != *b) return (*a > *b) ? 1 : -1;
        a++;
        b++;
    }
    if (*a) return 1;
    if (*b) return -1;
    return 0;
}

static inline void strcpy_t(char* dst, const char* src) {
    while (*src) {
        *dst++ = *src++;
    }
    *dst = 0;
}

static inline void memset_t(void* ptr, uint8_t val, uint16_t size) {
    uint8_t* p = (uint8_t*)ptr;
    for (uint16_t i = 0; i < size; i++) {
        p[i] = val;
    }
}

static inline void memcpy_t(void* dst, const void* src, uint16_t size) {
    uint8_t* d = (uint8_t*)dst;
    const uint8_t* s = (const uint8_t*)src;
    for (uint16_t i = 0; i < size; i++) {
        d[i] = s[i];
    }
}

#endif // TERNARY_H

/**
 * memory.c — Gestor de memoria en Base 60 (v2 — corregido)
 * 
 * Fixes:
 * - mem_alloc() retorna int16_t (no uint8_t) para error -1
 * - mem_get_base() con validación
 * - mem_print_map() implementada con salida real
 * - mem_read() con validación de color = libre
 */

#include "../include/ternary.h"

// =============================================================================
// ESTRUCTURAS
// =============================================================================

typedef struct {
    uint8_t data[BLOCK_SIZE];
    uint8_t color;
    uint8_t owner;
    uint8_t flags;
} __attribute__((packed)) mem_block_t;

typedef struct {
    uint8_t knot_positions[MEM_BLOCKS];
    uint8_t knot_colors[MEM_BLOCKS];
    uint8_t total_used;
    uint8_t total_free;
} __attribute__((packed)) memory_map_t;

// =============================================================================
// VARIABLES GLOBALES
// =============================================================================

static mem_block_t memory[MEM_BLOCKS];
static memory_map_t map;

// =============================================================================
// FUNCIONES
// =============================================================================

void mem_init(void) {
    memset_t(memory, 0, sizeof(memory));
    memset_t(&map, 0, sizeof(map));

    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        map.knot_positions[i] = i;
    }

    for (uint8_t i = 0; i < 5; i++) {
        memory[i].color = COLOR_KERNEL;
        memory[i].owner = 0;
        memory[i].flags = 0x08;
        map.knot_colors[i] = COLOR_KERNEL;
    }

    map.total_used = 5;
    map.total_free = MEM_BLOCKS - 5;
}

int16_t mem_alloc(uint8_t owner, uint8_t color) {
    uint8_t start = (map.total_used * 7) % MEM_BLOCKS;

    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        uint8_t idx = (start + i) % MEM_BLOCKS;

        if (memory[idx].color == COLOR_FREE) {
            memory[idx].color = color;
            memory[idx].owner = owner;
            memory[idx].flags = 0x01;
            map.knot_colors[idx] = color;
            map.total_used++;
            map.total_free--;
            return (int16_t)idx;
        }
    }

    return -1;
}

int8_t mem_free(uint8_t block_idx) {
    if (block_idx >= MEM_BLOCKS) return -1;
    if (memory[block_idx].flags & 0x08) return -1;

    memset_t(memory[block_idx].data, 0, BLOCK_SIZE);
    memory[block_idx].color = COLOR_FREE;
    memory[block_idx].owner = 0;
    memory[block_idx].flags = 0;
    map.knot_colors[block_idx] = COLOR_FREE;
    map.total_used--;
    map.total_free++;

    return 0;
}

void mem_free_all(uint8_t owner) {
    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        if (memory[i].owner == owner && !(memory[i].flags & 0x08)) {
            mem_free(i);
        }
    }
}

int8_t mem_read(babilonian_addr_t addr, uint8_t* value) {
    uint16_t linear = babilonian_to_linear(addr);
    uint8_t block = linear / BLOCK_SIZE;
    uint8_t offset = linear % BLOCK_SIZE;

    if (block >= MEM_BLOCKS) return -1;
    if (memory[block].color == COLOR_FREE) return -1;

    *value = memory[block].data[offset];
    return 0;
}

int8_t mem_write(babilonian_addr_t addr, uint8_t value) {
    uint16_t linear = babilonian_to_linear(addr);
    uint8_t block = linear / BLOCK_SIZE;
    uint8_t offset = linear % BLOCK_SIZE;

    if (block >= MEM_BLOCKS) return -1;
    if (memory[block].flags & 0x08) return -1;

    memory[block].data[offset] = value;
    memory[block].flags |= 0x02;
    return 0;
}

int8_t mem_get_base(uint8_t block_idx, babilonian_addr_t* result) {
    if (block_idx >= MEM_BLOCKS) return -1;
    *result = linear_to_babilonian(block_idx * BLOCK_SIZE);
    return 0;
}

void mem_get_status(uint8_t* used, uint8_t* free_count, uint8_t* locked) {
    *used = map.total_used;
    *free_count = map.total_free;

    uint8_t lock_count = 0;
    for (uint8_t i = 0; i < MEM_BLOCKS; i++) {
        if (memory[i].flags & 0x08) lock_count++;
    }
    *locked = lock_count;
}

uint8_t mem_get_color(uint8_t block_idx) {
    if (block_idx >= MEM_BLOCKS) return 0xFF;
    return memory[block_idx].color;
}

uint8_t mem_get_owner(uint8_t block_idx) {
    if (block_idx >= MEM_BLOCKS) return 0xFF;
    return memory[block_idx].owner;
}

uint8_t mem_get_flags(uint8_t block_idx) {
    if (block_idx >= MEM_BLOCKS) return 0xFF;
    return memory[block_idx].flags;
}

/**
 * scheduler.c — Planificador basado en Ciclos Mayas (v2 — corregido)
 * 
 * Fixes:
 * - select_next() no puede retornar PID 0 inválido
 * - sched_kill() libera memoria del proceso
 * - sched_get_info() retorna copia válida
 * - Nombre de hijos corregido (max 3, no 4)
 */

#include "../include/ternary.h"

// =============================================================================
// ESTRUCTURAS
// =============================================================================

typedef enum {
    PROC_DEAD = -1,
    PROC_SLEEPING = 0,
    PROC_ACTIVE = 1
} proc_state_t;

typedef struct {
    maya_pid_t pid;
    proc_state_t state;
    trit_t priority;
    uint8_t memory_block;
    uint16_t cpu_cycles;
    uint8_t quantum;
    uint8_t parent;
    uint8_t children[3];
    uint8_t n_children;
} __attribute__((packed)) process_t;

typedef struct {
    uint32_t global_tick;
    uint8_t current_pid;
    uint8_t tzolkin_day;
    uint8_t haab_day;
    uint8_t active_count;
    trit_t system_load;
} __attribute__((packed)) scheduler_state_t;

// =============================================================================
// VARIABLES GLOBALES
// =============================================================================

static process_t processes[MAX_PROCS];
static scheduler_state_t scheduler;

// =============================================================================
// FUNCIONES
// =============================================================================

void sched_init(void) {
    memset_t(processes, 0, sizeof(processes));

    for (uint8_t i = 0; i < MAX_PROCS; i++) {
        processes[i].pid = make_maya_pid(0);
        processes[i].state = PROC_DEAD;
        processes[i].priority = 0;
    }

    scheduler.global_tick = 0;
    scheduler.current_pid = 0;
    scheduler.tzolkin_day = 1;
    scheduler.haab_day = 1;
    scheduler.active_count = 0;
    scheduler.system_load = 0;

    processes[0].pid = make_maya_pid(0);
    processes[0].state = PROC_ACTIVE;
    processes[0].priority = 0;
    processes[0].memory_block = 0;
    scheduler.active_count = 1;
}

int8_t sched_create(uint8_t parent, trit_t priority) {
    for (uint8_t i = 1; i < MAX_PROCS; i++) {
        if (processes[i].state == PROC_DEAD) {
            processes[i].pid = make_maya_pid(scheduler.global_tick + i);
            processes[i].state = PROC_SLEEPING;
            processes[i].priority = priority;
            processes[i].memory_block = 0;
            processes[i].cpu_cycles = 0;
            processes[i].quantum = 0;
            processes[i].parent = parent;
            processes[i].n_children = 0;

            if (parent < MAX_PROCS && processes[parent].n_children < 3) {
                processes[parent].children[processes[parent].n_children] = i;
                processes[parent].n_children++;
            }

            scheduler.active_count++;
            return (int8_t)i;
        }
    }

    return -1;
}

int8_t sched_kill(uint8_t pid) {
    if (pid >= MAX_PROCS) return -1;
    if (processes[pid].state == PROC_DEAD) return -1;
    if (pid == 0) return -1;

    for (uint8_t i = 0; i < processes[pid].n_children; i++) {
        sched_kill(processes[pid].children[i]);
    }

    if (processes[pid].memory_block > 0) {
        mem_free(processes[pid].memory_block);
        processes[pid].memory_block = 0;
    }

    processes[pid].state = PROC_DEAD;
    scheduler.active_count--;

    return 0;
}

int8_t sched_sleep(uint8_t pid) {
    if (pid >= MAX_PROCS) return -1;
    if (processes[pid].state == PROC_DEAD) return -1;
    processes[pid].state = PROC_SLEEPING;
    return 0;
}

int8_t sched_wake(uint8_t pid) {
    if (pid >= MAX_PROCS) return -1;
    if (processes[pid].state == PROC_DEAD) return -1;
    processes[pid].state = PROC_ACTIVE;
    return 0;
}

static void update_maya_calendar(void) {
    scheduler.global_tick++;

    scheduler.tzolkin_day++;
    if (scheduler.tzolkin_day > TZOLKIN) {
        scheduler.tzolkin_day = 1;
    }

    scheduler.haab_day++;
    if (scheduler.haab_day > HAAB) {
        scheduler.haab_day = 1;
    }
}

static uint8_t select_next(void) {
    uint8_t start = scheduler.current_pid;
    trit_t best_priority = -2;
    uint8_t best_pid = 0;
    uint8_t found = 0;

    for (uint8_t i = 0; i < MAX_PROCS; i++) {
        uint8_t idx = (start + i + 1) % MAX_PROCS;

        if (processes[idx].state == PROC_ACTIVE) {
            trit_t cmp = trit_cmp(processes[idx].priority, best_priority);

            if (!found || cmp == 1 || (cmp == 0 && processes[idx].quantum < 3)) {
                best_priority = processes[idx].priority;
                best_pid = idx;
                found = 1;
            }
        }
    }

    return found ? best_pid : scheduler.current_pid;
}

static void update_system_load(void) {
    uint8_t active = scheduler.active_count;

    if (active <= 3) {
        scheduler.system_load = -1;
    } else if (active <= 10) {
        scheduler.system_load = 0;
    } else {
        scheduler.system_load = 1;
    }
}

uint8_t sched_tick(void) {
    update_maya_calendar();

    uint8_t next = select_next();

    if (next != scheduler.current_pid) {
        processes[scheduler.current_pid].quantum = 0;
        scheduler.current_pid = next;
    }

    processes[scheduler.current_pid].quantum++;
    processes[scheduler.current_pid].cpu_cycles++;

    if (processes[scheduler.current_pid].quantum >= 3) {
        processes[scheduler.current_pid].quantum = 0;
        return 1;
    }

    return 0;
}

uint8_t sched_get_current(void) {
    return scheduler.current_pid;
}

void sched_get_state(uint32_t* tick, uint8_t* tzolkin, uint8_t* haab, trit_t* load) {
    *tick = scheduler.global_tick;
    *tzolkin = scheduler.tzolkin_day;
    *haab = scheduler.haab_day;
    *load = scheduler.system_load;
}

int8_t sched_get_info(uint8_t pid, process_t* info) {
    if (pid >= MAX_PROCS) return -1;
    if (processes[pid].state == PROC_DEAD) return -1;

    memcpy_t(info, &processes[pid], sizeof(process_t));
    return 0;
}

int8_t sys_fork(void) {
    return sched_create(scheduler.current_pid,
                       processes[scheduler.current_pid].priority);
}

int8_t sys_exit(void) {
    return sched_kill(scheduler.current_pid);
}

int8_t sys_sleep(void) {
    return sched_sleep(scheduler.current_pid);
}

int8_t sys_wake(uint8_t pid) {
    return sched_wake(pid);
}

/**
 * kernel.c — Kernel Ternario Ancestral v2 (Nivel 2)
 * 
 * Nivel 2: Terminal + Shell completo
 * - VGA con scroll
 * - Terminal con buffer de línea
 * - Shell con comandos: ps, mem, fs, cal, fork, kill, help, clear, echo
 * - Keyboard driver completo con scancode set 1
 * - Serial como logging secundario
 * 
 * Tamaño: ~6KB de código
 * Memoria: 3.5KB (60 bloques × 60 bytes)
 */

#include "../include/ternary.h"

// =============================================================================
// VGA — Pantalla con scroll (0xB8000)
// =============================================================================

#define VGA_ADDR  0xB8000
#define VGA_WIDTH 80
#define VGA_HEIGHT 25

static uint16_t* vga_buffer = (uint16_t*)VGA_ADDR;
static uint8_t vga_x = 0;
static uint8_t vga_y = 0;
static uint8_t vga_color = 0x07;

static const char* color_names[] = {
    "black", "blue", "green", "cyan",
    "red", "magenta", "brown", "lightgray",
    "darkgray", "lightblue", "lightgreen", "lightcyan",
    "lightred", "lightmagenta", "yellow", "white"
};

void vga_init(void) {
    for (int i = 0; i < VGA_WIDTH * VGA_HEIGHT; i++) {
        vga_buffer[i] = 0x0720;
    }
    vga_x = 0;
    vga_y = 0;
}

static void vga_scroll(void) {
    for (int i = 0; i < VGA_WIDTH * (VGA_HEIGHT - 1); i++) {
        vga_buffer[i] = vga_buffer[i + VGA_WIDTH];
    }
    for (int i = VGA_WIDTH * (VGA_HEIGHT - 1); i < VGA_WIDTH * VGA_HEIGHT; i++) {
        vga_buffer[i] = 0x0720;
    }
    vga_y = VGA_HEIGHT - 1;
}

void vga_putc(char c) {
    if (c == '\n') {
        vga_x = 0;
        vga_y++;
        if (vga_y >= VGA_HEIGHT) vga_scroll();
        return;
    }
    if (c == '\b') {
        if (vga_x > 0) {
            vga_x--;
            vga_buffer[vga_y * VGA_WIDTH + vga_x] = 0x0720;
        }
        return;
    }
    if (c == '\t') {
        vga_x = (vga_x + 8) & ~7;
        if (vga_x >= VGA_WIDTH) {
            vga_x = 0;
            vga_y++;
            if (vga_y >= VGA_HEIGHT) vga_scroll();
        }
        return;
    }

    uint16_t entry = (vga_color << 8) | (uint8_t)c;
    vga_buffer[vga_y * VGA_WIDTH + vga_x] = entry;

    vga_x++;
    if (vga_x >= VGA_WIDTH) {
        vga_x = 0;
        vga_y++;
        if (vga_y >= VGA_HEIGHT) vga_scroll();
    }
}

void vga_puts(const char* str) {
    while (*str) vga_putc(*str++);
}

void vga_set_color(uint8_t fg, uint8_t bg) {
    vga_color = (bg << 4) | fg;
}

void vga_print_trit(trit_t t) {
    if (t == -1) {
        vga_set_color(0x04, 0);
        vga_putc('-');
    } else if (t == 0) {
        vga_set_color(0x07, 0);
        vga_putc('0');
    } else {
        vga_set_color(0x02, 0);
        vga_putc('+');
    }
    vga_set_color(0x07, 0);
}

// =============================================================================
// SERIAL — Logging (0x3F8)
// =============================================================================

#define SERIAL_PORT 0x3F8

void serial_init(void) {
    outb(SERIAL_PORT + 1, 0x00);
    outb(SERIAL_PORT + 3, 0x80);
    outb(SERIAL_PORT + 0, 0x0C);
    outb(SERIAL_PORT + 1, 0x00);
    outb(SERIAL_PORT + 3, 0x03);
    outb(SERIAL_PORT + 2, 0xC7);
    outb(SERIAL_PORT + 4, 0x0B);
}

void serial_putc(char c) {
    while (!(inb(SERIAL_PORT + 5) & 0x20));
    outb(SERIAL_PORT, c);
}

void serial_puts(const char* str) {
    while (*str) serial_putc(*str++);
}

void serial_print_num(int16_t num) {
    char buf[8];
    int i = 0;

    if (num < 0) {
        serial_putc('-');
        num = -num;
    }
    if (num == 0) {
        serial_putc('0');
        return;
    }
    while (num > 0 && i < 7) {
        buf[i++] = '0' + (num % 10);
        num /= 10;
    }
    while (i > 0) serial_putc(buf[--i]);
}

// =============================================================================
// NÚMEROS A STRING
// =============================================================================

void num_to_str(int16_t num, char* buf) {
    int i = 0;
    int neg = 0;

    if (num < 0) {
        neg = 1;
        num = -num;
    }
    if (num == 0) {
        buf[0] = '0';
        buf[1] = 0;
        return;
    }
    while (num > 0 && i < 6) {
        buf[i++] = '0' + (num % 10);
        num /= 10;
    }
    if (neg) buf[i++] = '-';

    for (int j = 0; j < i / 2; j++) {
        char tmp = buf[j];
        buf[j] = buf[i - j - 1];
        buf[i - j - 1] = tmp;
    }
    buf[i] = 0;
}

// =============================================================================
// QUIPU FILESYSTEM
// =============================================================================

#define MAX_FILES 33

typedef struct {
    char name[8];
    uint8_t size;
    uint8_t block;
    uint8_t type;
    uint8_t permissions;
} __attribute__((packed)) quipu_file_t;

static quipu_file_t files[MAX_FILES];
static uint8_t n_files = 0;

void fs_init(void) {
    memset_t(files, 0, sizeof(files));

    files[0].name[0] = '/';
    for (uint8_t j = 1; j < 8; j++) files[0].name[j] = 0;
    files[0].type = 1;
    n_files = 1;
}

int8_t fs_create(const char* name, uint8_t type) {
    if (n_files >= MAX_FILES) return -1;
    if (strlen_t(name) > 7) return -1;

    strcpy_t(files[n_files].name, name);
    files[n_files].type = type;
    files[n_files].size = 0;
    files[n_files].block = 0;
    files[n_files].permissions = 0x07;

    n_files++;
    return (int8_t)(n_files - 1);
}

int8_t fs_find(const char* name) {
    uint8_t len = strlen_t(name);
    if (len > 7) return -1;

    for (uint8_t i = 0; i < n_files; i++) {
        if (strcmp_t(files[i].name, name) == 0) return i;
    }
    return -1;
}

int8_t fs_delete(uint8_t file_id) {
    if (file_id >= n_files || file_id == 0) return -1;

    for (uint8_t i = file_id; i < n_files - 1; i++) {
        files[i] = files[i + 1];
    }
    n_files--;
    return 0;
}

uint8_t fs_count(void) {
    return n_files;
}

const char* fs_get_name(uint8_t idx) {
    if (idx >= n_files) return "?";
    return files[idx].name;
}

uint8_t fs_get_type(uint8_t idx) {
    if (idx >= n_files) return 0;
    return files[idx].type;
}

// =============================================================================
// IDT — Interrupciones
// =============================================================================

typedef struct {
    uint16_t base_lo;
    uint16_t sel;
    uint8_t always0;
    uint8_t flags;
    uint16_t base_hi;
} __attribute__((packed)) idt_entry_t;

typedef struct {
    uint16_t limit;
    uint32_t base;
} __attribute__((packed)) idt_ptr_t;

static idt_entry_t idt[256];
static idt_ptr_t idtp;

void idt_set_gate(uint8_t num, uint32_t base, uint16_t sel, uint8_t flags) {
    idt[num].base_lo = base & 0xFFFF;
    idt[num].base_hi = (base >> 16) & 0xFFFF;
    idt[num].sel = sel;
    idt[num].always0 = 0;
    idt[num].flags = flags;
}

void idt_install(void) {
    idtp.limit = sizeof(idt_entry_t) * 256 - 1;
    idtp.base = (uint32_t)&idt;

    for (uint8_t i = 0; i < 256; i++) {
        idt_set_gate(i, 0, 0, 0);
    }

    idt_set_gate(32, 0, 0x08, 0x8E);
    idt_set_gate(33, 0, 0x08, 0x8E);

    asm volatile("lidt %0" : : "m"(idtp));
}

