static void cmd_fork(void) {
    int8_t new_pid = sys_fork();
    if (new_pid >= 0) {
        char num_buf[8];
        vga_puts("  Process created: PID ");
        num_to_str(new_pid, num_buf);
        vga_puts(num_buf);
        vga_putc('\n');
