content:
# Makefile para Kernel Ternario Ancestral v2
# Compilación cruzada para i386 (x86)

CC = i686-elf-gcc
AS = nasm
LD = i686-elf-ld
OBJCOPY = objcopy

CFLAGS = -ffreestanding -O2 -Wall -Wextra -nostdlib -nostdinc -fno-builtin \
         -fno-stack-protector -nostartfiles -nodefaultlibs -m32
ASFLAGS = -f elf32
LDFLAGS = -m elf_i386 -T linker.ld

BOOT_SRC = boot/boot.asm
BOOT_OBJ = boot/boot.bin

KERNEL_SRC = src/kernel.c src/memory.c src/scheduler.c
KERNEL_OBJ = kernel.o memory.o scheduler.o

KERNEL_BIN = ternary_kernel.bin
ISO_FILE = ternary_os.iso

all: $(ISO_FILE)

$(BOOT_OBJ): $(BOOT_SRC)
	$(AS) -f bin $< -o $@

kernel.o: src/kernel.c include/ternary.h
	$(CC) $(CFLAGS) -c src/kernel.c -o kernel.o

memory.o: src/memory.c include/ternary.h
	$(CC) $(CFLAGS) -c src/memory.c -o memory.o

scheduler.o: src/scheduler.c include/ternary.h
	$(CC) $(CFLAGS) -c src/scheduler.c -o scheduler.o

linker.ld:
	@echo 'OUTPUT_FORMAT("binary")' > linker.ld
	@echo 'ENTRY(kernel_main)' >> linker.ld
	@echo 'SECTIONS' >> linker.ld
	@echo '{' >> linker.ld
	@echo '  . = 0x10000;' >> linker.ld
	@echo '  .text : { *(.text) }' >> linker.ld
	@echo '  .rodata : { *(.rodata) }' >> linker.ld
	@echo '  .data : { *(.data) }' >> linker.ld
	@echo '  .bss : { *(.bss) }' >> linker.ld
	@echo '}' >> linker.ld

$(KERNEL_BIN): $(KERNEL_OBJ) linker.ld
	$(LD) $(LDFLAGS) $(KERNEL_OBJ) -o $@

disk.img: $(BOOT_OBJ) $(KERNEL_BIN)
	dd if=/dev/zero of=$@ bs=512 count=20
	dd if=$(BOOT_OBJ) of=$@ bs=512 count=1 conv=notrunc
	dd if=$(KERNEL_BIN) of=$@ bs=512 seek=1 conv=notrunc

$(ISO_FILE): disk.img
	mkdir -p iso/boot/grub
	cp disk.img iso/boot/ternary.img
	@echo 'set timeout=0' > iso/boot/grub/grub.cfg
	@echo 'set default=0' >> iso/boot/grub/grub.cfg
	@echo '' >> iso/boot/grub/grub.cfg
	@echo 'menuentry "Ternary Ancestral Kernel v2" {' >> iso/boot/grub/grub.cfg
	@echo '  linux16 /boot/ternary.img' >> iso/boot/grub/grub.cfg
	@echo '}' >> iso/boot/grub/grub.cfg
	genisoimage -R -b boot/grub/grub.cfg -no-emul-boot -o $@ iso/

run: $(ISO_FILE)
	qemu-system-i386 -cdrom $(ISO_FILE) -m 4M -serial stdio

debug: $(ISO_FILE)
	qemu-system-i386 -cdrom $(ISO_FILE) -m 4M -serial stdio -s -S &
	gdb -ex "target remote :1234"

run-disk: disk.img
	qemu-system-i386 -drive file=disk.img,format=raw -m 4M -serial stdio

clean:
	rm -f $(BOOT_OBJ) $(KERNEL_OBJ) $(KERNEL_BIN) disk.img $(ISO_FILE)
	rm -f linker.ld
	rm -rf iso/

info: $(KERNEL_BIN)
	@echo "=== Ternary Ancestral Kernel v2 ==="
	@echo "Boot loader: $(shell wc -c < $(BOOT_OBJ)) bytes"
	@echo "Kernel:      $(shell wc -c < $(KERNEL_BIN)) bytes"
	@echo "Total:       $(shell expr $(shell wc -c < $(BOOT_OBJ)) + $(shell wc -c < $(KERNEL_BIN))) bytes"
	@echo ""
	@echo "Features:"
	@echo "  - Nivel 2: Terminal + Shell interactivo"
	@echo "  - VGA con scroll y colores"
	@echo "  - Keyboard driver (scancode set 1)"
	@echo "  - Serial logging (9600 baud)"
	@echo "  - Ternary logic {-1, 0, +1}"
	@echo "  - Memory: Base 60 (Babylonian)"
	@echo "  - Scheduler: Maya cycles"
	@echo "  - Filesystem: Quipu"
	@echo ""
	@echo "Shell commands:"
	@echo "  help, ps, mem, fs, cal, fork, kill, echo, clear, trit, b60, halt"

.PHONY: all clean run debug run-disk info

/**
 * ternary.h — Core ternary definitions for userspace kernel
 * 
 * This kernel runs ON TOP of Linux.
 * Linux provides: processes, memory, filesystem, I/O, network
 * We provide: ternary logic, base-60 addressing, Maya scheduling, Quipu FS
 */

#ifndef TERNARY_H
#define TERNARY_H

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <sys/time.h>
#include <fcntl.h>
#include <dirent.h>
#include <errno.h>
#include <time.h>
#include <termios.h>
#include <pwd.h>

// =============================================================================
// CONSTANTS
// =============================================================================

#define TAK_VERSION     "2.0"
#define TAK_NAME        "Ternary Ancestral Kernel"
#define TAK_HOME        ".tak"
#define TAK_MAX_PROCS   33
#define TAK_MAX_FILES   33
#define TAK_MAX_MEM     60
#define TAK_BLOCK_SIZE  60
#define TAK_CMD_MAX     256
#define TAK_HISTORY     50

#define TZOLKIN_DAYS    260
#define HAAB_DAYS       365
#define BASE_60         60

// Colors
#define COLOR_RESET     "\033[0m"
#define COLOR_BOLD      "\033[1m"
#define COLOR_RED       "\033[31m"
#define COLOR_GREEN     "\033[32m"
#define COLOR_YELLOW    "\033[33m"
#define COLOR_BLUE      "\033[34m"
#define COLOR_MAGENTA   "\033[35m"
#define COLOR_CYAN      "\033[36m"
#define COLOR_WHITE     "\033[37m"
#define COLOR_GRAY      "\033[90m"
#define COLOR_BG_RED    "\033[41m"
#define COLOR_BG_GREEN  "\033[42m"
#define COLOR_BG_YELLOW "\033[43m"

// =============================================================================
// TYPES
// =============================================================================

typedef int8_t trit_t;

typedef struct {
    uint16_t tzolkin;
    uint8_t haab;
} maya_pid_t;

typedef struct {
    uint8_t high;
    uint8_t low;
} babilonian_addr_t;

typedef enum {
    PROC_DEAD = -1,
    PROC_SLEEPING = 0,
    PROC_ACTIVE = 1
} proc_state_t;

typedef struct {
    maya_pid_t pid;
    proc_state_t state;
    trit_t priority;
    pid_t linux_pid;
    char name[32];
    uint64_t cpu_cycles;
    uint64_t memory_bytes;
} tak_process_t;

typedef struct {
    char name[32];
    uint8_t type;       // 0=file, 1=dir, 2=exec
    uint32_t size;
    char path[256];
} tak_file_t;

typedef struct {
    maya_pid_t pid;
    uint32_t tzolkin_day;
    uint32_t haab_day;
    uint64_t global_tick;
    trit_t system_load;
} maya_calendar_t;

// =============================================================================
// TERNARY OPERATIONS
// =============================================================================

static inline trit_t trit_add(trit_t a, trit_t b) {
    int r = a + b;
    if (r > 1) return 1;
    if (r < -1) return -1;
    return (trit_t)r;
}

static inline trit_t trit_mul(trit_t a, trit_t b) {
    if (a == 0 || b == 0) return 0;
    return (a == b) ? 1 : -1;
}

static inline trit_t trit_neg(trit_t a) { return -a; }

static inline trit_t trit_cmp(trit_t a, trit_t b) {
    if (a > b) return 1;
    if (a < b) return -1;
    return 0;
}

// =============================================================================
// BABILONIAN ADDRESSING
// =============================================================================

static inline babilonian_addr_t linear_to_b60(uint32_t addr) {
    babilonian_addr_t r;
    r.high = addr / BASE_60;
    r.low = addr % BASE_60;
    return r;
}

static inline uint32_t b60_to_linear(babilonian_addr_t a) {
    return a.high * BASE_60 + a.low;
}

// =============================================================================
// MAYA CALENDAR
// =============================================================================

static inline maya_pid_t make_maya_pid(uint32_t counter) {
    maya_pid_t p;
    p.tzolkin = (counter % TZOLKIN_DAYS) + 1;
    p.haab = (counter % HAAB_DAYS) + 1;
    return p;
}

#endif // TERNARY_H

/**
 * scheduler.c — Maya-cycle scheduler wrapping Linux processes
 *
 * Each TAK "process" maps to a Linux process (fork/exec or thread).
 * Scheduling is done by Linux; we track state with Maya calendar IDs.
 */

#include "ternary.h"

// =============================================================================
// STATE
// =============================================================================

static tak_process_t processes[TAK_MAX_PROCS];
static maya_calendar_t calendar;
static uint32_t next_pid_counter = 0;

// =============================================================================
// INIT
// =============================================================================

void sched_init(void) {
    memset(processes, 0, sizeof(processes));
    for (int i = 0; i < TAK_MAX_PROCS; i++) {
        processes[i].state = PROC_DEAD;
        processes[i].linux_pid = -1;
    }

    calendar.global_tick = 0;
    calendar.tzolkin_day = 1;
    calendar.haab_day = 1;
    calendar.system_load = 0;

    /* PID 0 = init process (the shell itself) */
    processes[0].pid = make_maya_pid(0);
    processes[0].state = PROC_ACTIVE;
    processes[0].linux_pid = getpid();
    strncpy(processes[0].name, "init", 4);
    processes[0].priority = 0;
}

// =============================================================================
// CREATE / KILL
// =============================================================================

int sched_create(const char* name, trit_t priority) {
    for (int i = 1; i < TAK_MAX_PROCS; i++) {
        if (processes[i].state == PROC_DEAD) {
            processes[i].pid = make_maya_pid(next_pid_counter++);
            processes[i].state = PROC_SLEEPING;
            processes[i].priority = priority;
            processes[i].linux_pid = -1;
            processes[i].cpu_cycles = 0;
            processes[i].memory_bytes = 0;
            strncpy(processes[i].name, name, 31);
            processes[i].name[31] = 0;
            return i;
        }
    }
    return -1;
}

int sched_kill(int tak_pid) {
    if (tak_pid < 0 || tak_pid >= TAK_MAX_PROCS) return -1;
    if (processes[tak_pid].state == PROC_DEAD) return -1;
    if (tak_pid == 0) return -1; /* can't kill init */

    /* Kill the Linux process if alive */
    if (processes[tak_pid].linux_pid > 0) {
        kill(processes[tak_pid].linux_pid, SIGTERM);
        usleep(50000);
        if (kill(processes[tak_pid].linux_pid, 0) == 0) {
            kill(processes[tak_pid].linux_pid, SIGKILL);
        }
        waitpid(processes[tak_pid].linux_pid, NULL, 0);
    }

    processes[tak_pid].state = PROC_DEAD;
    processes[tak_pid].linux_pid = -1;
    return 0;
}

// =============================================================================
// LAUNCH — fork+exec a Linux command, register as TAK process
// =============================================================================

int sched_exec(const char* name, const char* path, char* const argv[]) {
    int slot = sched_create(name, 0);
    if (slot < 0) return -1;

    pid_t pid = fork();
    if (pid == 0) {
        /* Child: become the new process group leader */
        setpgid(0, 0);
        execvp(path, argv);
        fprintf(stderr, "tak: exec '%s' failed: %s\n", path, strerror(errno));
        _exit(127);
    } else if (pid > 0) {
        processes[slot].linux_pid = pid;
        processes[slot].state = PROC_ACTIVE;
        return slot;
    } else {
        processes[slot].state = PROC_DEAD;
        return -1;
    }
}

// =============================================================================
// WAIT — reap children, update TAK process table
// =============================================================================

void sched_reap(void) {
    int status;
    pid_t pid;
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        for (int i = 1; i < TAK_MAX_PROCS; i++) {
            if (processes[i].linux_pid == pid) {
                processes[i].state = PROC_DEAD;
                processes[i].linux_pid = -1;
                break;
            }
        }
    }
}

// =============================================================================
// TICK — advance Maya calendar
// =============================================================================

void sched_tick(void) {
    calendar.global_tick++;

    calendar.tzolkin_day++;
    if (calendar.tzolkin_day > TZOLKIN_DAYS) calendar.tzolkin_day = 1;

    calendar.haab_day++;
    if (calendar.haab_day > HAAB_DAYS) calendar.haab_day = 1;

    /* Update system load (ternary) */
    int active = 0;
    for (int i = 1; i < TAK_MAX_PROCS; i++) {
        if (processes[i].state == PROC_ACTIVE) active++;
    }
    if (active <= 3) calendar.system_load = -1;
    else if (active <= 10) calendar.system_load = 0;
    else calendar.system_load = 1;

    /* Reap zombies */
    sched_reap();
}

// =============================================================================
// QUERY
// =============================================================================

int sched_get_current(void) {
    return 0; /* always init */
}

maya_calendar_t* sched_get_calendar(void) {
    return &calendar;
}

tak_process_t* sched_get_process(int i) {
    if (i < 0 || i >= TAK_MAX_PROCS) return NULL;
    return &processes[i];
}

int sched_active_count(void) {
    int c = 0;
    for (int i = 1; i < TAK_MAX_PROCS; i++) {
        if (processes[i].state == PROC_ACTIVE) c++;
    }
    return c;
}

/**
 * filesystem.c — Quipu filesystem over real directory
 *
 * The Quipu FS is a directory (~/.tak/quipu/) where each "knot" is a file.
 * File metadata is stored in a manifest (JSON-like plain text).
 * This gives us real persistence with minimal overhead.
 */

#include "ternary.h"

// =============================================================================
// PATHS
// =============================================================================

static char tak_home[512];
static char quipu_root[512];

void fs_set_home(const char* home) {
    strncpy(tak_home, home, 511);
    snprintf(quipu_root, 512, "%s/quipu", tak_home);
}

const char* fs_get_root(void) {
    return quipu_root;
}

// =============================================================================
// INIT — create directories if missing
// =============================================================================

void fs_init(void) {
    mkdir(tak_home, 0755);
    mkdir(quipu_root, 0755);
}

// =============================================================================
// CREATE — write a file into Quipu
// =============================================================================

int fs_create(const char* name, const char* data, uint32_t size) {
    char path[768];
    snprintf(path, sizeof(path), "%s/%s", quipu_root, name);

    FILE* f = fopen(path, "w");
    if (!f) return -1;
    fwrite(data, 1, size, f);
    fclose(f);
    return 0;
}

// =============================================================================
// READ — read a file from Quipu
// =============================================================================

int fs_read(const char* name, char* buf, uint32_t bufsize) {
    char path[768];
    snprintf(path, sizeof(path), "%s/%s", quipu_root, name);

    FILE* f = fopen(path, "r");
    if (!f) return -1;

    size_t n = fread(buf, 1, bufsize - 1, f);
    buf[n] = 0;
    fclose(f);
    return (int)n;
}

// =============================================================================
// DELETE
// =============================================================================

int fs_delete(const char* name) {
    char path[768];
    snprintf(path, sizeof(path), "%s/%s", quipu_root, name);
    return unlink(path);
}

// =============================================================================
// EXISTS
// =============================================================================

int fs_exists(const char* name) {
    char path[768];
    snprintf(path, sizeof(path), "%s/%s", quipu_root, name);
    struct stat st;
    return stat(path, &st) == 0;
}

// =============================================================================
// LIST — return all files in Quipu
// =============================================================================

int fs_list(tak_file_t* files, int max_files) {
    DIR* d = opendir(quipu_root);
    if (!d) return 0;

    int count = 0;
    struct dirent* ent;
    while ((ent = readdir(d)) != NULL && count < max_files) {
        if (ent->d_name[0] == '.') continue;

        strncpy(files[count].name, ent->d_name, 31);
        files[count].name[31] = 0;

        char path[768];
        snprintf(path, sizeof(path), "%s/%s", quipu_root, ent->d_name);
        struct stat st;
        if (stat(path, &st) == 0) {
            files[count].size = (uint32_t)st.st_size;
            files[count].type = S_ISDIR(st.st_mode) ? 1 : 0;
        } else {
            files[count].size = 0;
            files[count].type = 0;
        }
        strncpy(files[count].path, path, 255);
        count++;
    }
    closedir(d);
    return count;
}

// =============================================================================
// SIZE — get file size
// =============================================================================

uint32_t fs_size(const char* name) {
    char path[768];
    snprintf(path, sizeof(path), "%s/%s", quipu_root, name);
    struct stat st;
    if (stat(path, &st) != 0) return 0;
    return (uint32_t)st.st_size;
}

/**
 * memory.c — Ternary memory manager (Base 60)
 *
 * Wraps malloc with ternary tracking.
 * 60 "blocks" tracked, each can hold data up to TAK_BLOCK_SIZE.
 * Actual allocation uses malloc underneath; we just track metadata.
 */

#include "ternary.h"

typedef struct {
    void* ptr;
    uint32_t size;
    uint8_t owner;      /* TAK process ID */
    uint8_t color;      /* block type (0=free, 1=kernel, 2=process, 3=data) */
    uint8_t flags;      /* 1=used */
    char label[16];
} mem_block_t;

static mem_block_t blocks[TAK_MAX_MEM];
static uint32_t total_allocated = 0;
static uint32_t total_freed = 0;

void mem_init(void) {
    memset(blocks, 0, sizeof(blocks));
    total_allocated = 0;
    total_freed = 0;

    /* Mark first 5 as kernel */
    for (int i = 0; i < 5; i++) {
        blocks[i].color = 1;
        blocks[i].owner = 0;
        blocks[i].flags = 1;
        blocks[i].label[0] = 'K';
    }
}

int mem_alloc(int owner, uint8_t color, uint32_t size, const char* label) {
    /* Find free slot */
    for (int i = 0; i < TAK_MAX_MEM; i++) {
        if (!blocks[i].flags) {
            blocks[i].ptr = malloc(size);
            if (!blocks[i].ptr) return -1;
            blocks[i].size = size;
            blocks[i].owner = owner;
            blocks[i].color = color;
            blocks[i].flags = 1;
            if (label) strncpy(blocks[i].label, label, 15);
            total_allocated += size;
            return i;
        }
    }
    return -1;
}

int mem_free(int block) {
    if (block < 0 || block >= TAK_MAX_MEM) return -1;
    if (!blocks[block].flags) return -1;

    free(blocks[block].ptr);
    total_freed += blocks[block].size;
    memset(&blocks[block], 0, sizeof(mem_block_t));
    return 0;
}

void mem_free_owner(int owner) {
    for (int i = 0; i < TAK_MAX_MEM; i++) {
        if (blocks[i].flags && blocks[i].owner == owner) {
            mem_free(i);
        }
    }
}

void* mem_get_ptr(int block) {
    if (block < 0 || block >= TAK_MAX_MEM) return NULL;
    return blocks[block].ptr;
}

uint32_t mem_get_size(int block) {
    if (block < 0 || block >= TAK_MAX_MEM) return 0;
    return blocks[block].size;
}

int mem_get_active_count(void) {
    int c = 0;
    for (int i = 0; i < TAK_MAX_MEM; i++) {
        if (blocks[i].flags) c++;
    }
    return c;
}

uint32_t mem_get_total_allocated(void) {
    return total_allocated;
}

mem_block_t* mem_get_block(int i) {
    if (i < 0 || i >= TAK_MAX_MEM) return NULL;
    return &blocks[i];
}

const char* mem_color_name(uint8_t color) {
    switch (color) {
        case 0: return "free";
        case 1: return "kernel";
        case 2: return "process";
        case 3: return "data";
        case 4: return "code";
        case 5: return "stack";
        default: return "unknown";
    }
}

const char* mem_color_ansi(uint8_t color) {
    switch (color) {
        case 0: return COLOR_GRAY;
        case 1: return COLOR_RED;
        case 2: return COLOR_GREEN;
        case 3: return COLOR_BLUE;
        case 4: return COLOR_YELLOW;
        case 5: return COLOR_MAGENTA;
        default: return COLOR_WHITE;
    }
}

