// =============================================================================
// COMMAND DISPATCH
// =============================================================================

int run_single(char* line) {
    while (*line == ' ') line++;
    if (*line == 0) return 0;

    /* Check alias */
    char alias_buf[TAK_CMD_MAX];
    char* argv[64];
    int argc = 0;

    char* tok = strtok(line, " \t");
    if (!tok) return 0;

    const char* expansion = alias_lookup(tok);
    if (expansion) {
        strncpy(alias_buf, expansion, TAK_CMD_MAX - 1);
        strcat(alias_buf, " ");
        /* Append remaining args */
        char* rest = strtok(NULL, "");
        if (rest) strncat(alias_buf, rest, TAK_CMD_MAX - strlen(alias_buf) - 1);
        tok = strtok(alias_buf, " \t");
    }

    while (tok && argc < 64) {
        argv[argc++] = tok;
        tok = strtok(NULL, " \t");
    }
    argv[argc] = NULL;

    if (argc == 0) return 0;

    /* Builtins */
    if (strcmp(argv[0], "help") == 0 || strcmp(argv[0], "?") == 0) { cmd_help(); return 0; }
    if (strcmp(argv[0], "ps") == 0) { cmd_ps(); return 0; }
    if (strcmp(argv[0], "fork") == 0) { cmd_fork(argc, argv); return 0; }
    if (strcmp(argv[0], "kill") == 0) { cmd_kill_tak(argc, argv); return 0; }
    if (strcmp(argv[0], "cd") == 0) { cmd_cd(argc, argv); return 0; }
    if (strcmp(argv[0], "pwd") == 0) { cmd_pwd(); return 0; }
    if (strcmp(argv[0], "ls") == 0) { cmd_ls(argc, argv); return 0; }
    if (strcmp(argv[0], "mem") == 0) { cmd_mem(); return 0; }
    if (strcmp(argv[0], "malloc") == 0) { cmd_malloc(argc, argv); return 0; }
    if (strcmp(argv[0], "free") == 0) { cmd_free_block(argc, argv); return 0; }
    if (strcmp(argv[0], "fs") == 0) { cmd_fs(); return 0; }
    if (strcmp(argv[0], "touch") == 0) { cmd_touch(argc, argv); return 0; }
    if (strcmp(argv[0], "cat") == 0) { cmd_cat(argc, argv); return 0; }
    if (strcmp(argv[0], "rm") == 0) { cmd_rm(argc, argv); return 0; }
    if (strcmp(argv[0], "cal") == 0) { cmd_cal(); return 0; }
    if (strcmp(argv[0], "trit") == 0) { cmd_trit(argc, argv); return 0; }
    if (strcmp(argv[0], "b60") == 0) { cmd_b60(argc, argv); return 0; }
    if (strcmp(argv[0], "whoami") == 0) { cmd_whoami(); return 0; }
    if (strcmp(argv[0], "uname") == 0) { cmd_uname(); return 0; }
    if (strcmp(argv[0], "uptime") == 0) { cmd_uptime(); return 0; }
    if (strcmp(argv[0], "clear") == 0 || argv[0][0] == 12) { printf("\033[2J\033[H"); return 0; }
    if (strcmp(argv[0], "neofetch") == 0) { cmd_neofetch(); return 0; }
    if (strcmp(argv[0], "halt") == 0 || strcmp(argv[0], "exit") == 0) {
        state_save();
        printf("\n  " COLOR_GREEN "✓" COLOR_RESET " Goodbye.\n\n");
        exit(0);
    }

    /* Alias management */
    if (strcmp(argv[0], "alias") == 0) {
        if (argc < 2) { alias_list(); return 0; }
        char* eq = strchr(argv[1], '=');
        if (eq) {
            *eq = 0;
            alias_add(argv[1], eq + 1);
            printf("  alias %s=%s\n", argv[1], eq + 1);
        } else {
            const char* val = alias_lookup(argv[1]);
            if (val) printf("  %s=%s\n", argv[1], val);
            else printf("  alias: %s: not found\n", argv[1]);
        }
        return 0;
    }
    if (strcmp(argv[0], "unalias") == 0) {
        if (argc < 2) { printf("  Usage: unalias <name>\n"); return 0; }
        for (int i = 0; i < n_aliases; i++) {
            if (strcmp(aliases[i].name, argv[1]) == 0) {
                aliases[i] = aliases[--n_aliases];
                printf("  Removed alias '%s'\n", argv[1]);
                return 0;
            }
        }
        printf("  alias: %s: not found\n", argv[1]);
        return 0;
    }
    if (strcmp(argv[0], "history") == 0) { history_show(); return 0; }

    /* Jobs */
    if (strcmp(argv[0], "jobs") == 0) { job_list(); return 0; }
    if (strcmp(argv[0], "fg") == 0) {
        if (argc < 2) { printf("  Usage: fg <job_id>\n"); return 0; }
        if (job_fg(atoi(argv[1])) != 0)
            printf("  No such job: %s\n", argv[1]);
        return 0;
    }

    /* External command: fork+exec */
    char path_buf[1024];

    /* Try PATH lookup */
    const char* path_env = getenv("PATH");
    if (path_env && argv[0][0] != '/') {
        char* path_copy = strdup(path_env);
        char* saveptr;
        char* dir = strtok_r(path_copy, ":", &saveptr);
        int found = 0;
        while (dir) {
            snprintf(path_buf, sizeof(path_buf), "%s/%s", dir, argv[0]);
            if (access(path_buf, X_OK) == 0) {
                found = 1;
                break;
            }
            dir = strtok_r(NULL, ":", &saveptr);
        }
        free(path_copy);
        if (!found) {
            snprintf(path_buf, sizeof(path_buf), "%s", argv[0]);
        }
    } else {
        snprintf(path_buf, sizeof(path_buf), "%s", argv[0]);
    }

    /* Check for background (& at end) */
    int background = 0;
    if (argc > 1 && strcmp(argv[argc - 1], "&") == 0) {
        background = 1;
        argv[--argc] = NULL;
    }

    pid_t pid = fork();
    if (pid == 0) {
        /* Child */
        setpgid(0, 0);
        execvp(path_buf, argv);
        fprintf(stderr, "tak: %s: %s\n", argv[0], strerror(errno));
        _exit(127);
    } else if (pid > 0) {
        if (background) {
            setpgid(pid, pid);
            int jid = job_add(pid, argv[0]);
            printf("  [%d] %d\n", jid, pid);
        } else {
            foreground_pid = pid;
            setpgid(pid, shell_pgid);
            tcsetpgrp(STDIN_FILENO, pid);
            waitpid(pid, NULL, 0);
            tcsetpgrp(STDIN_FILENO, shell_pgid);
            foreground_pid = -1;
        }
    } else {
        printf("  fork: %s\n", strerror(errno));
    }

    return 0;
}

// =============================================================================
// PIPE EXECUTION
// =============================================================================

void run_piped(char** cmds, int ncmds) {
    int prev_fd = -1;
    int fd[2];

    for (int i = 0; i < ncmds; i++) {
        pipe(fd);

        pid_t pid = fork();
        if (pid == 0) {
            /* Child */
            setpgid(0, 0);
            if (prev_fd != -1) {
                dup2(prev_fd, STDIN_FILENO);
                close(prev_fd);
            }
            if (i < ncmds - 1) {
                dup2(fd[1], STDOUT_FILENO);
            }
            close(fd[0]);
            close(fd[1]);

            /* Run command */
            char buf[TAK_CMD_MAX];
            strncpy(buf, cmds[i], TAK_CMD_MAX - 1);
            run_single(buf);
            _exit(0);
        }

        /* Parent */
        if (prev_fd != -1) close(prev_fd);
        close(fd[1]);
        prev_fd = fd[0];
    }

    /* Wait for last child */
    if (prev_fd != -1) close(prev_fd);
    int status;
    wait(&status);
}

// =============================================================================
// LINE DISPATCHER — pipes, chains, redirection
// =============================================================================

void parse_and_run(char* line) {
    while (*line == ' ') line++;
    if (*line == 0) return;

    history_add(line);

    /* Check for pipes */
    char* pipe_cmds[16];
    int n_pipes = 0;

    char* saveptr;
    char* pipe_tok = strtok_r(line, "|", &saveptr);
    while (pipe_tok && n_pipes < 16) {
        while (*pipe_tok == ' ') pipe_tok++;
        pipe_cmds[n_pipes++] = pipe_tok;
        pipe_tok = strtok_r(NULL, "|", &saveptr);
    }

    if (n_pipes > 1) {
        run_piped(pipe_cmds, n_pipes);
        return;
    }

    /* Check for ; and && chains */
    char* chain_cmds[16];
    int n_chains = 0;
    int chain_and[16] = {0};

    char* chain_tok = strtok_r(line, ";", &saveptr);
    while (chain_tok && n_chains < 16) {
        while (*chain_tok == ' ') chain_tok++;

        /* Check for && */
        char* and_pos = strstr(chain_tok, "&&");
        if (and_pos) {
            *and_pos = 0;
            and_pos += 2;
            while (*and_pos == ' ') and_pos++;
            chain_cmds[n_chains] = chain_tok;
            chain_and[n_chains] = 1;
            n_chains++;
            chain_cmds[n_chains] = and_pos;
            chain_and[n_chains] = 0;
            n_chains++;
        } else {
            chain_cmds[n_chains] = chain_tok;
            chain_and[n_chains] = 0;
            n_chains++;
        }

        chain_tok = strtok_r(NULL, ";", &saveptr);
    }

    int last_status = 0;
    for (int i = 0; i < n_chains; i++) {
        if (chain_and[i] && last_status != 0) continue;

        char buf[TAK_CMD_MAX];
        strncpy(buf, chain_cmds[i], TAK_CMD_MAX - 1);
        buf[TAK_CMD_MAX - 1] = 0;

        /* Check for redirection */
        char* redir_out = NULL;
        char* redir_append = NULL;
        char* redir_in = NULL;
        int redir_fd = -1;

        char* r;
        if ((r = strstr(buf, ">>"))) {
            *r = 0; r += 2;
            while (*r == ' ') r++;
            redir_append = r;
            /* Strip trailing spaces */
            char* end = r + strlen(r) - 1;
            while (end > r && *end == ' ') *end-- = 0;
        } else if ((r = strstr(buf, ">"))) {
            *r = 0; r++;
            while (*r == ' ') r++;
            redir_out = r;
            char* end = r + strlen(r) - 1;
            while (end > r && *end == ' ') *end-- = 0;
        }
        if ((r = strstr(buf, "<"))) {
            *r = 0; r++;
            while (*r == ' ') r++;
            redir_in = r;
            char* end = r + strlen(r) - 1;
            while (end > r && *end == ' ') *end-- = 0;
        }

        /* Apply redirections */
        int saved_stdout = -1, saved_stdin = -1;

        if (redir_out) {
            saved_stdout = dup(STDOUT_FILENO);
            int fd = open(redir_out, O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (fd >= 0) { dup2(fd, STDOUT_FILENO); close(fd); }
        } else if (redir_append) {
            saved_stdout = dup(STDOUT_FILENO);
            int fd = open(redir_append, O_WRONLY | O_CREAT | O_APPEND, 0644);
            if (fd >= 0) { dup2(fd, STDOUT_FILENO); close(fd); }
        }

        if (redir_in) {
            saved_stdin = dup(STDIN_FILENO);
            int fd = open(redir_in, O_RDONLY);
            if (fd >= 0) { dup2(fd, STDIN_FILENO); close(fd); }
        }

        last_status = run_single(buf);

        /* Restore fds */
        if (saved_stdout >= 0) { dup2(saved_stdout, STDOUT_FILENO); close(saved_stdout); }
        if (saved_stdin >= 0) { dup2(saved_stdin, STDIN_FILENO); close(saved_stdin); }
    }
}

// =============================================================================
// SIGNALS
// =============================================================================

void handle_sigint(int sig) {
    (void)sig;
    if (foreground_pid > 0) {
        kill(foreground_pid, SIGINT);
    } else {
        printf("\n");
        show_prompt();
    }
}

void handle_sigtstp(int sig) {
    (void)sig;
    if (foreground_pid > 0) {
        kill(foreground_pid, SIGTSTP);
        job_add(foreground_pid, "(stopped)");
        printf("\n  [" COLOR_YELLOW "stopped" COLOR_RESET "] %d\n", foreground_pid);
        foreground_pid = -1;
        tcsetpgrp(STDIN_FILENO, shell_pgid);
        show_prompt();
    }
}

void handle_sigchld(int sig) {
    (void)sig;
    job_reap();
}

// =============================================================================
// MAIN
// =============================================================================

int main(int argc, char* argv[]) {
    /* Home directory */
    const char* home = getenv("HOME");
    if (!home) home = "/tmp";
    snprintf(tak_home, sizeof(tak_home), "%s/%s", home, TAK_HOME);
    fs_set_home(tak_home);
    snprintf(state_path, sizeof(state_path), "%s/state", tak_home);
    getcwd(cwd, sizeof(cwd));

    /* Init */
    printf(COLOR_GRAY "  [init] %s/" COLOR_RESET "\n", tak_home);
    fs_init();
    mem_init();
    sched_init();
    state_load();

    /* Signals */
    shell_pgid = getpid();
    setpgid(0, shell_pgid);
    signal(SIGINT, handle_sigint);
    signal(SIGTSTP, handle_sigtstp);
    signal(SIGCHLD, handle_sigchld);

    /* -f script mode */
    if (argc >= 3 && strcmp(argv[1], "-f") == 0) {
        FILE* f = fopen(argv[2], "r");
        if (!f) {
            fprintf(stderr, "tak: %s: %s\n", argv[2], strerror(errno));
            return 1;
        }
        char line[TAK_CMD_MAX];
        while (fgets(line, sizeof(line), f)) {
            line[strcspn(line, "\n")] = 0;
            if (line[0] == '#' || line[0] == 0) continue;
            printf(COLOR_GRAY "  $ " COLOR_RESET "%s\n", line);
            parse_and_run(line);
        }
        fclose(f);
        state_save();
        return 0;
    }

    /* -c single command */
    if (argc >= 3 && strcmp(argv[1], "-c") == 0) {
        parse_and_run(argv[2]);
        return 0;
    }

    /* Interactive mode */
    show_banner();

    char line[TAK_CMD_MAX];
    while (1) {
        sched_tick();
        job_reap();
        show_prompt();

        if (read_line(line, sizeof(line)) < 0) {
            printf("\n");
            break;
        }

        parse_and_run(line);
    }

    state_save();
    return 0;
}

